// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Signer signer;

    function setUp() public {
        c = new C("", 0, address(this));
        signer = new Signer();
    }

    function testFuzz_property(address to, uint256 nonce) public {
        // keep recipient in the admissible domain (nonzero, not an address that would clash)
        vm.assume(to != address(0));
        vm.assume(to != address(this));
        vm.assume(to != address(c));
        vm.assume(to != address(signer));

        // Build a fully valid long-call order whose maker is an ERC-1271 signer helper,
        // with zero-value/empty asset lists so no other token movement is needed.
        C.ERC20Asset[] memory erc20s = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721s = new C.ERC721Asset[](0);
        C.Order memory order = C.Order({
            maker: address(signer),
            isCall: true,
            isLong: true,
            baseAsset: address(signer), // has code, satisfies the baseAsset check
            strike: 0,
            premium: 0,
            duration: 1 days,
            expiration: block.timestamp + 1,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: erc20s,
            erc721Assets: erc721s
        });

        uint256[] memory noFloors = new uint256[](0);
        bytes memory bogusSig = hex"00"; // forces ERC-1271 path on the helper

        // Filling the order mints the opposite (short) position NFT to the caller.
        uint256 positionId = c.fillOrder(order, bogusSig, noFloors);

        // General rule: after any successful transferFrom(from, to, id), ownerOf(id) == to.
        c.transferFrom(address(this), to, positionId);
        assertTrue(c.ownerOf(positionId) == to);
    }
}

// ERC-1271 signer that also emulates a token returning success (value 1) for any call.
contract Signer {
    function isValidSignature(bytes32, bytes calldata) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }

    fallback() external {
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(uint256 id, address to, address attacker) public {
        // The id space is entirely un-minted: c has no public minting surface, so
        // _ownerOf[id] is address(0) for every fuzzed id.
        vm.assume(to != address(0));

        // Attacker passes from == msg.sender (attacker) so the NOT_AUTHORIZED
        // check passes; only the WRONG_FROM check should block the transfer.
        vm.prank(attacker);
        bool ok;
        try c.transferFrom(attacker, to, id) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: transferFrom on a never-minted token id must always revert
        // (the token has no owner, so from == _ownerOf[id] can never hold).
        assertTrue(!ok);
    }
}

