pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Maker maker;
    MockERC20 token;

    function setUp() public {
        c = new C("", 0, address(this));
        maker = new Maker();
        token = new MockERC20();
    }

    function testFuzz_property(address actor, address to, uint256 salt) public {
        vm.assume(actor != address(0) && actor != address(maker) && actor != address(token) && actor != address(c) && actor != address(this));
        vm.assume(to != address(0) && to != actor);

        // Build a valid long-call order signed (EIP-1271) by the maker contract.
        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: 1 days,
            expiration: block.timestamp + 1 hours,
            nonce: salt,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        bytes memory emptySig = new bytes(0);
        uint256[] memory noFloorIds = new uint256[](0);

        vm.prank(actor);
        c.fillOrder(order, emptySig, noFloorIds);

        // The maker now owns the long position NFT id = uint256(orderHash).
        require(c.ownerOf(uint256(orderHash)) == address(maker), "setup failed");

        // A third party (actor) that is not the owner, approved, or operator
        // attempts to steal the token. General rule: an unauthorized caller can
        // never change ownership; the transfer must revert.
        vm.prank(actor);
        bool ok;
        try c.transferFrom(address(maker), to, uint256(orderHash)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok && c.ownerOf(uint256(orderHash)) == address(maker));
    }
}

contract Maker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }
}

contract MockERC20 {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}

