pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(
        uint256 strike,
        uint256 premium,
        uint256 nonce,
        uint256 duration,
        uint256 expiration
    ) public {
        vm.warp(1);

        ERC20Mock base = new ERC20Mock();
        Signer maker = new Signer();

        C.Order memory order;
        order.maker = address(maker);
        order.isCall = false;
        order.isLong = false;
        order.baseAsset = address(base);
        order.strike = bound(strike, 0, 1e30);
        order.premium = bound(premium, 0, 1e30);
        order.duration = bound(duration, 0, 10_000 days - 1);
        order.expiration = bound(expiration, 2, 1e18);
        order.nonce = nonce;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new C.ERC20Asset[](0);
        order.erc721Assets = new C.ERC721Asset[](0);

        // Fill a valid (ERC-1271-signed) order; the fuzzer-supplied fields are honored.
        uint256 positionId = c.fillOrder(order, new bytes(0), new uint256[](0));

        // General rule: a position token owned by the caller can never be transferred
        // to the zero address — the transfer must revert.
        bool ok;
        try c.transferFrom(address(this), address(0), positionId) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "transfer to address(0) must revert");
    }
}

// Adversarial counterparties: an ERC-1271 signer (so the fuzzer can mint a position
// without producing an ECDSA signature) and a mock ERC20 the settlement calls hit.
contract Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract ERC20Mock {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expOffset
    ) public {
        FakeToken tok = new FakeToken();

        strike = bound(strike, 1, 1e30);
        premium = bound(premium, 0, 1e30);
        duration = bound(duration, 1, 10_000 days - 1);
        expOffset = bound(expOffset, 1, 1_000_000);

        address maker = vm.addr(1);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: false,
            isLong: false,
            baseAsset: address(tok),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + expOffset,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 digest = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(1, digest);
        bytes memory sig = abi.encodePacked(r, s, v);

        vm.prank(maker);
        c.fillOrder(order, sig, new uint256[](0));

        uint256 positionId = uint256(c.hashOppositeOrder(order));

        bool ok;
        address own;
        try c.ownerOf(positionId) returns (address o) {
            ok = true;
            own = o;
        } catch {
            ok = false;
        }

        assertTrue(ok && own == maker);
    }
}

contract FakeToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}
